ALTER TABLE users ADD COLUMN coins_earned INTEGER NOT NULL DEFAULT 0;
ALTER TABLE quests ADD COLUMN coins INTEGER NOT NULL DEFAULT 0;
UPDATE users SET coins_spent = 0;
CREATE TABLE IF NOT EXISTS store_items ( id TEXT PRIMARY KEY, type TEXT NOT NULL, name TEXT NOT NULL, name_es TEXT, visual TEXT NOT NULL, price INTEGER, level INTEGER NOT NULL DEFAULT 0, reward_level INTEGER, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
